const kbPending=new Set();
async function tryApprovedKB(last){
 const norm=x=>String(x).normalize('NFKC').toLowerCase().replace(/[\s?？!！。.,，]+/g,'');
 if(!(server||cloud)||!TravelStarters.arrivalQuestions.flat().some(x=>norm(x)===norm(last.text)))return false;
 const key=conversationEpoch+':'+last.revision;if(kbPending.has(key))return true;if(last.kbTried)return false;
 kbPending.add(key);last.kbTried=true;const epoch=conversationEpoch,rev=last.revision,gen=generation;
 try{const payload={text:last.text,city:last.context?.city||state.facts.city,language:last.language||state.language};const out=server?await api('kb',payload):await cloudApi({action:'kb',...payload});
  if(epoch!==conversationEpoch||rev!==state.revision||gen!==generation)return true;
  if(!out.matched)return false;
  last.assistance=out.answer;last.aiPending=false;last.answerId=crypto.randomUUID();last.offers=[];
  window.TravelOpsClient?.answer(out.answer,last);render();latest();$('model-note').textContent='已返回版本绑定的标准答案 · 本轮零模型调用；不是实时服务确认。';if(call.active&&!call.muted)speakReply();return true;
 }catch(_){return false;}finally{kbPending.delete(key);}
}

